corrected_code:
const express = require('express');
const { CrmDeal } = require('../models/crmDeal');

const app = express();
const partnerApp = express({ mergeParams: true });

app.use('/partners/:partnerId/leads', (req, res, next) => {
  if (!req.user || !req.user.partnerId) {
    return res.status(401).json({ error: 'Partner authentication required' });
  }

  // Validate that caller is affiliated with the partnerId in the route path
  if (req.user.partnerId !== req.params.partnerId) {
    return res.status(403).json({ error: 'Forbidden: unauthorized partner access' });
  }
  next();
}, partnerApp);

partnerApp.get('/deal/:dealId', async (req, res) => {
  // Query strictly requires deal to belong to the authorized partner
  const deal = await CrmDeal.findOne({
    _id: req.params.dealId,
    partnerId: req.params.partnerId
  });

  if (!deal) {
    return res.status(404).json({ error: 'Deal registration not found for this partner' });
  }

  res.json({
    dealId: deal.id,
    clientName: deal.clientName,
    dealAmountUsd: deal.expectedValue,
    commissionPct: deal.commissionPercentage,
    notes: deal.salesNotes
  });
});

app.listen(7000);
